// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/mfa", wrapper.VerifyMfa)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/mfa/enroll", wrapper.BeginMfaEnroll)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/mfa/enroll/confirm", wrapper.ConfirmMfaEnroll)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/refresh", wrapper.RefreshSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/reauth", wrapper.Reauth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/brokers/{account_id}/login-url", wrapper.GetBrokerLoginUrl)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/brokers/callback/zerodha", wrapper.BrokerCallbackZerodha)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/brokers/callback/upstox", wrapper.BrokerCallbackUpstox)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/instruments/search", wrapper.SearchInstruments)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/instruments/{id}", wrapper.GetInstrument)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/instruments/{id}/expiries", wrapper.GetExpiries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/optionchain/{underlying_id}", wrapper.GetOptionChain)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/marketdata/candles", wrapper.GetCandles)

	return m
}

