// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Password step; returns an mfa_token for the TOTP step
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revokes the current session and clears the refresh cookie
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// VerifyMfa TOTP step for an enrolled user; starts a session
	// (POST /auth/mfa)
	VerifyMfa(ctx context.Context, request VerifyMfaRequestObject) (VerifyMfaResponseObject, error)
	// BeginMfaEnroll First login only; generates a TOTP secret to scan
	// (POST /auth/mfa/enroll)
	BeginMfaEnroll(ctx context.Context, request BeginMfaEnrollRequestObject) (BeginMfaEnrollResponseObject, error)
	// ConfirmMfaEnroll Confirms enrollment with a first code and starts a session
	// (POST /auth/mfa/enroll/confirm)
	ConfirmMfaEnroll(ctx context.Context, request ConfirmMfaEnrollRequestObject) (ConfirmMfaEnrollResponseObject, error)
	// Reauth Re-checks password + TOTP; returns a reauth_token for the X-Reauth header
	// (POST /auth/reauth)
	Reauth(ctx context.Context, request ReauthRequestObject) (ReauthResponseObject, error)
	// RefreshSession Rotates the refresh cookie and returns a new access token
	// (POST /auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// BrokerCallbackUpstox Upstox OAuth redirect; exchanges the code and starts the engine session
	// (GET /brokers/callback/upstox)
	BrokerCallbackUpstox(ctx context.Context, request BrokerCallbackUpstoxRequestObject) (BrokerCallbackUpstoxResponseObject, error)
	// BrokerCallbackZerodha Kite Connect redirect; exchanges request_token and starts the engine session
	// (GET /brokers/callback/zerodha)
	BrokerCallbackZerodha(ctx context.Context, request BrokerCallbackZerodhaRequestObject) (BrokerCallbackZerodhaResponseObject, error)
	// GetBrokerLoginUrl Daily broker login URL (Kite Connect login / Upstox OAuth dialog)
	// (GET /brokers/{account_id}/login-url)
	GetBrokerLoginUrl(ctx context.Context, request GetBrokerLoginUrlRequestObject) (GetBrokerLoginUrlResponseObject, error)
	// GetHealth Gateway health with dependency checks
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// SearchInstruments Active instruments whose trading symbol or underlying symbol starts with q
	// (GET /instruments/search)
	SearchInstruments(ctx context.Context, request SearchInstrumentsRequestObject) (SearchInstrumentsResponseObject, error)
	// GetInstrument One instrument (active or expired)
	// (GET /instruments/{id})
	GetInstrument(ctx context.Context, request GetInstrumentRequestObject) (GetInstrumentResponseObject, error)
	// GetExpiries Active option expiries of an underlying (today IST onwards), nearest first
	// (GET /instruments/{id}/expiries)
	GetExpiries(ctx context.Context, request GetExpiriesRequestObject) (GetExpiriesResponseObject, error)
	// GetCandles Historical bars from ClickHouse (entitled instruments only)
	// (GET /marketdata/candles)
	GetCandles(ctx context.Context, request GetCandlesRequestObject) (GetCandlesResponseObject, error)
	// GetOptionChain Option chain with IV, Greeks, PCR and max pain (F-MD-3)
	// (GET /optionchain/{underlying_id})
	GetOptionChain(ctx context.Context, request GetOptionChainRequestObject) (GetOptionChainResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

